// Shape of a parser generated by `build/vite-plugin-jison.ts` from a `.jison` file.

/**
 * Source location tracked by the Jison lexer (lines are 1-based, columns 0-based).
 */
export interface JisonLocation {
  /** line where the token starts */
  first_line: number
  /** line where the token ends */
  last_line: number
  /** column where the token starts */
  first_column: number
  /** column just past the end of the token */
  last_column: number
  /** character offsets, present when the lexer runs with `ranges: true` */
  range?: [number, number]
}

/**
 * The generated lexer. `parse()` drives it through `setInput()` and `lex()`.
 */
export interface JisonLexer {
  /** text of the current token */
  yytext: string
  /** length of the current token */
  yyleng: number
  /** current line (0-based) */
  yylineno: number
  /** location of the current token */
  yylloc: JisonLocation
  /** shared state installed by the parser */
  yy: Record<string, any>
  /** lexer options from the grammar's `%options` */
  options: Record<string, any>
  /** starts lexing a new input */
  setInput(input: string, yy?: Record<string, any>): JisonLexer
  /** returns the next token */
  lex(): number | string
  /** enters a start condition (alias of `pushState`) */
  begin(condition: string): void
  /** pushes a start condition */
  pushState(condition: string): void
  /** leaves the current start condition */
  popState(): string
  /** returns the start condition `n` levels down the stack */
  topState(n?: number): string
}

/**
 * Details passed to `parseError()`.
 */
export interface JisonParseErrorHash {
  /** text of the offending token */
  text: string
  /** name of the offending token */
  token: string | null
  /** line of the offending token (0-based) */
  line: number
  /** location of the offending token */
  loc: JisonLocation
  /** tokens that would have been accepted */
  expected?: string[]
  /** whether the parser can recover */
  recoverable?: boolean
}

/**
 * A parser instance. Instances share the generated tables but not `yy`.
 */
export interface JisonParser {
  /** shared state visible to grammar actions as `yy` */
  yy: Record<string, any>
  /** the lexer used by `parse()`; can be replaced by a filtering lexer */
  lexer: JisonLexer
  /** parses the input and returns the value of the start rule */
  parse(input: string): any
  /** reports a syntax error; throws by default */
  parseError(message: string, hash: JisonParseErrorHash): void
}

/**
 * Default export of a `.jison` module: a ready instance plus the `Parser` constructor.
 */
export interface JisonParserModule extends JisonParser {
  /** creates a fresh parser; use one per `parse()` call */
  Parser: new () => JisonParser
}
